{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "A student must be a Tennessee resident entitled to attend public school. Students enrolled in a home school, or in a church-related school under the parent arrangements specified in the bill, would not qualify.",
      "rationale": "Conveys residency, public-school entitlement, and the exclusions, but does not explain which parental arrangements trigger the church-related-school exclusion."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "eligible Tennessee students to attend approved private schools in the state",
      "rationale": "Conveys in-state private-school attendance and approval, but omits the category I, II, or III restriction and the commissioner’s approval under state board rules."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The department of education would administer the program, subject to available funding, and adopt rules that include an appeal process for denied applications.",
      "rationale": "Together with the opening creation statement and subsequent initial-year and later-year provisions, conveys the program, administering agency, funding contingency, and continuing availability."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "For 2025–2026, the department could award up to 20,000 scholarships in order of completed applications. Half would be reserved for students whose household income is no more than 300% of the amount required to qualify for free or reduced-price lunch, or who meet either of two eligibility definitions cited in the bill. The other half would be open to all eligible students.",
      "rationale": "Conveys the cap, application order, equal allocation, and income threshold, but leaves the alternative eligibility groups unidentified and describes the department’s mandatory award directive as discretionary."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "In later years, the department could raise the next year’s limit by up to 5,000 if applications exceed 75% of available scholarships and funds are available; otherwise, the limit would stay the same.",
      "rationale": "Conveys the later-year timing, discretionary increase, funding condition, numerical limits, and unchanged-cap rule."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "If applications exceed available scholarships, priority would go first to prior-year recipients, then to students in the bill’s lowest-income or cited eligibility groups, then to students under the 300% income threshold, then to current public school students and students eligible to enter public kindergarten, and finally to other eligible students.",
      "rationale": "Conveys the tier structure and oversubscription condition, but omits the 100% threshold, identification of the alternative eligibility groups, and completed-application receipt order within later tiers."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "To receive a scholarship, a student or parent must apply, enroll the student in a private school that satisfies compulsory attendance requirements, and keep the student out of a K–12 public school during the scholarship year.",
      "rationale": "Conveys the principal participation requirements, but omits the expanded definitions of parent and public school and does not specify a completed application to the department."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "The department could award out of order to comply with an appeal decision.",
      "rationale": "Conveys the exception to award order for an appeal outcome; the preceding discussion identifies appeals as involving denied applications."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Each scholarship would equal the base funding amount cited in the bill.",
      "rationale": "Conveys the scholarship amount, while the opening sentence identifies the program as state-funded."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "It must pay private-school tuition and fees first. Remaining funds could pay for specified school materials and uniforms, qualifying tutoring and transportation, educational technology, qualifying summer and afterschool academic programs, certain courses, exams and credentials, and qualifying educational therapy.",
      "rationale": "Conveys tuition-and-fees priority and limits subsequent spending to specified authorized educational expenses."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "Remaining funds could pay for specified school materials and uniforms",
      "rationale": "Conveys materials and uniforms as allowable remaining-fund expenses, but does not identify textbooks and curricula or the requirement that the recipient’s school require the items."
    },
    {
      "proposition_id": "P12",
      "status": "partial",
      "summary_quote": "qualifying tutoring and transportation",
      "rationale": "Identifies tutoring as an allowable expense but does not state that the tutor or tutoring facility must meet department requirements."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "qualifying tutoring and transportation",
      "rationale": "Identifies transportation as allowable but omits travel to and from the recipient’s school and payment to a fee-for-service provider meeting department requirements."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "educational technology",
      "rationale": "Conveys an authorized educational technology expense but omits the covered hardware, devices, and fees and the department-requirements condition."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "qualifying summer and afterschool academic programs",
      "rationale": "Conveys the program categories but omits the authorized expense types, department requirements, specialized-afterschool limitation, and express exclusion of afterschool childcare."
    },
    {
      "proposition_id": "P16",
      "status": "partial",
      "summary_quote": "certain courses, exams and credentials",
      "rationale": "Conveys broad expense categories but not the early-postsecondary, postsecondary-admission, and industry-credential limitations or department approval."
    },
    {
      "proposition_id": "P17",
      "status": "partial",
      "summary_quote": "qualifying educational therapy",
      "rationale": "Identifies educational therapy as allowable but does not specify that the therapists must meet department requirements."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "Unspent funds would carry over until an account-closing event",
      "rationale": "Conveys continued availability of unspent account funds between years until a closure event."
    },
    {
      "proposition_id": "P19",
      "status": "partial",
      "summary_quote": "Unspent funds would carry over until an account-closing event, such as graduation, public-school enrollment, withdrawal or disqualification. Remaining funds would then return to the state treasurer for future scholarships.",
      "rationale": "Conveys closure, several triggers, and return of funds, but omits an approved equivalency credential, completion of 13 K–12 years, and the noncompliance basis for department disqualification."
    },
    {
      "proposition_id": "P20",
      "status": "partial",
      "summary_quote": "Scholarship recipients in grades 3–11 would take an annual qualifying standardized test or the applicable Tennessee assessment.",
      "rationale": "Conveys grades, annual testing, and the two alternatives, but omits national standardization and alignment to the school’s instructional plan under state board rules."
    },
    {
      "proposition_id": "P21",
      "status": "partial",
      "summary_quote": "Participating private schools would give parents the results",
      "rationale": "Conveys provision of results to parents but does not expressly assign annual administration of the assessment to each participating school."
    },
    {
      "proposition_id": "P22",
      "status": "partial",
      "summary_quote": "beginning June 30, 2026, report results annually to the comptroller’s office of research and education accountability",
      "rationale": "Conveys the reporting recipient and annual schedule, but omits the required form, demographic analysis categories, and permission to use aggregated, deidentified data; it also does not clearly state the recurring June 30 deadline."
    },
    {
      "proposition_id": "P23",
      "status": "full",
      "summary_quote": "report results annually to the comptroller’s office of research and education accountability, which would report to legislative education committees",
      "rationale": "Conveys the office’s onward reporting of the annual assessment results to legislative education committees."
    },
    {
      "proposition_id": "P24",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The regulatory discussion does not state that participating private schools are autonomous or are not state agents."
    },
    {
      "proposition_id": "P25",
      "status": "partial",
      "summary_quote": "The bill would limit additional state regulation of participating private schools and would not require them to change their creed, practices, admissions, hiring or curriculum.",
      "rationale": "Conveys protection against required institutional changes, but omits LEA authority and the narrowly tailored program-enforcement boundary on additional rules."
    },
    {
      "proposition_id": "P26",
      "status": "partial",
      "summary_quote": "could not award a scholarship for a year in which the student participates in either of two other education account programs named in the bill",
      "rationale": "Conveys the same-year participation bar but does not identify the Tennessee education savings account pilot program or individualized education account program."
    },
    {
      "proposition_id": "P27",
      "status": "partial",
      "summary_quote": "recipients would not retain a right to special education services from their local education agency through an individualized education program, while retaining the equitable-service rights described in the bill",
      "rationale": "Conveys loss of the LEA individualized-education-program entitlement, but does not explain that retained IDEA equitable services are through an individualized service plan on the same basis as other non-public-school students."
    },
    {
      "proposition_id": "P28",
      "status": "full",
      "summary_quote": "Scholarships could not be paid directly to students or parents.",
      "rationale": "Conveys the prohibition on direct payment to recipients or parents."
    },
    {
      "proposition_id": "P29",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not state the scholarship’s classification as a state or local public benefit."
    },
    {
      "proposition_id": "P30",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not address the income-tax treatment of program funds."
    },
    {
      "proposition_id": "P31",
      "status": "full",
      "summary_quote": "The department would deny an application if the student could not establish lawful presence in the United States",
      "rationale": "Conveys mandatory denial when the student cannot establish lawful presence."
    },
    {
      "proposition_id": "P32",
      "status": "partial",
      "summary_quote": "adopt rules that include an appeal process for denied applications",
      "rationale": "Conveys department rulemaking and the required appeal process, but omits compliance with the Uniform Administrative Procedures Act."
    },
    {
      "proposition_id": "P33",
      "status": "partial",
      "summary_quote": "beginning in 2025–2026, the bill would provide additional state funds to a local education agency whose TISA allocation falls and whose non-virtual average daily membership declines, under the bill’s stated calculation",
      "rationale": "Conveys timing and the allocation and enrollment conditions, but does not explain restoration to the immediately preceding year’s allocation or the continuing-protection exception."
    },
    {
      "proposition_id": "P34",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The general funding description does not convey the distinct 2026–2027 continuing protection for prior recipients or its inclusion of prior-year supplemental funds in the protected amount."
    },
    {
      "proposition_id": "P35",
      "status": "partial",
      "summary_quote": "the bill would provide additional state funds to a local education agency",
      "rationale": "Conveys state funding but omits the prohibition on also receiving additional funds under § 49-3-108(b) or (c)."
    },
    {
      "proposition_id": "P36",
      "status": "partial",
      "summary_quote": "It would provide a one-time, $2,000 state-funded bonus, subject to appropriation, for each qualifying public-school teacher employed in 2024–2025.",
      "rationale": "Conveys the amount, one-time nature, funding, appropriation condition, and employment year, but leaves the K–12 scope and existing-educator definition unstated."
    },
    {
      "proposition_id": "P37",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not address exclusion of the bonuses from TISA or their treatment as neither salary payments nor supplements."
    },
    {
      "proposition_id": "P38",
      "status": "partial",
      "summary_quote": "It would also direct 80% of the privilege tax collected under the cited section to an account for public-school building construction and maintenance",
      "rationale": "Conveys the percentage and use, but leaves the tax provision unidentified and omits the council’s distribution duty, treasurer administration, and LEAs as the account beneficiaries."
    },
    {
      "proposition_id": "P39",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Saying that specified needs will be considered does not convey any of the required allocation factors or identify the treasurer as decision-maker."
    },
    {
      "proposition_id": "P40",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not mention severability or preservation of valid provisions and applications."
    },
    {
      "proposition_id": "P41",
      "status": "full",
      "summary_quote": "That tax provision would take effect July 1, 2025; the rest of the bill would take effect upon becoming law.",
      "rationale": "Conveys both effective dates and correctly distinguishes the tax-distribution amendment from the remaining provisions."
    }
  ]
}
